package com.pipican.boss;

import java.util.*;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;

/** Curving returning oath, breakable chain anchors and staggered missing-row surges. */
public final class HrothgarCombat {
    public static final String OATH="returning_oath",CHAINS="drowned_chains",ROWERS="rowing_dead";
    private final RegionalBossEntity boss;private final RegionalCombatClock clock;private Vec3 origin=Vec3.ZERO,mark=Vec3.ZERO;private double heading;
    private List<Boolean> broken=List.of(false,false,false,false),rowerBroken=List.of(false,false,false,false);private int phase=1,safeGap=1,oathDelay=-1,rowIndex,sequence;
    public HrothgarCombat(RegionalBossEntity boss){this.boss=boss;var d=BossDesigns.require("hrothgar_drowned_jarl");clock=new RegionalCombatClock(Map.of(OATH,time(d,0),CHAINS,time(d,1),ROWERS,time(d,2),"basic",new RegionalCombatClock.Timing(18,20,55)));}
    private static RegionalCombatClock.Timing time(BossDesigns.Design d,int i){var a=d.abilities().get(i);return new RegionalCombatClock.Timing(a.windup(),a.recovery(),a.cooldown());}
    public RegionalCombatClock clock(){return clock;}public int brokenLinks(){return(int)broken.stream().filter(Boolean::booleanValue).count();}public int brokenRowers(){return(int)rowerBroken.stream().filter(Boolean::booleanValue).count();}public int safeGap(){return safeGap;}public int pendingOathTicks(){return oathDelay;}public int rowIndex(){return rowIndex;}public Vec3 rowLanePosition(int i){if(i<0||i>=4)throw new IndexOutOfBoundsException();return row(i).get(12);}public Vec3 chainAnchor(int i){if(i<0||i>=4)throw new IndexOutOfBoundsException();return anchor(i);}public Vec3 rowerPosition(int i){if(i<0||i>=4)throw new IndexOutOfBoundsException();return row(i).getLast();}public Vec3 safeRowPosition(){return origin.add(side().scale((safeGap-1.5)*3.5)).add(forward().scale(4));}public Vec3 oathPoint(int i,boolean returning){var path=oathPath();return path.get(returning?path.size()-1-i:i);}
    public boolean begin(String id,LivingEntity target){if(target==null||!target.isAlive()||!boss.insideArena(target.position())||!clock.begin(id))return false;origin=boss.position();mark=target.position();heading=Math.atan2(mark.z-origin.z,mark.x-origin.x);phase=clock.phase();if(phase==2){safeGap=(safeGap+1)%4;sequence=(sequence+1)%2;heading+=.1;boss.playSound(SoundEvents.RAVAGER_ROAR,1.1f,.7f);}if(id.equals(CHAINS))broken=List.of(false,false,false,false);if(id.equals(ROWERS)){rowIndex=0;safeGap=Math.floorMod(safeGap+sequence,4);rowerBroken=List.of(false,false,false,false);}if(id.equals(OATH))oathDelay=-1;return true;}
    private Vec3 forward(){return new Vec3(Math.cos(heading),0,Math.sin(heading));}private Vec3 side(){Vec3 f=forward();return new Vec3(-f.z,0,f.x);}private Vec3 anchor(int i){double a=i*Math.PI/2+Math.PI/4;return origin.add(Math.cos(a)*6,0,Math.sin(a)*6);}
    private List<Vec3> oathPath(){var out=new ArrayList<Vec3>();Vec3 f=forward(),s=side();for(int i=0;i<=24;i++){double t=i/24.0;Vec3 p=origin.add(f.scale(-7+14*t)).add(s.scale(Math.sin(t*Math.PI)*3.2));if(boss.insideArena(p))out.add(p);}return out;}
    private List<Vec3> chain(int i){var pts=new ArrayList<Vec3>();Vec3 a=anchor(i),b=anchor((i+1)%4);for(int n=0;n<=20;n++){Vec3 p=a.lerp(b,n/20.0);if(boss.insideArena(p))pts.add(p);}return pts;}
    private List<Vec3> row(int i){var pts=new ArrayList<Vec3>();Vec3 s=side(),f=forward();double lateral=(i-1.5)*3.5;for(int n=0;n<=24;n++){Vec3 p=origin.add(s.scale(lateral)).add(f.scale(-7+n*.5));if(boss.insideArena(p))pts.add(p);}return pts;}
    public void tick(ServerLevel l){String id=clock.active();if(id.equals(CHAINS)&&!clock.resolved())checkLinks(l);if(id.equals(ROWERS)&&!clock.resolved())checkRowerHits(l);if(!id.isEmpty()&&!clock.resolved()&&clock.remaining()%5==0)telegraph(l,id);
        if(id.equals(ROWERS)&&clock.resolved()&&rowIndex<4){if(sequence>0)sequence--;else{if(rowIndex!=safeGap&&!rowerBroken.get(rowIndex))strike(l,row(rowIndex),.28f);rowIndex++;sequence=rowIndex<4?8:-1;}}
        if(id.equals(OATH)&&clock.resolved()&&oathDelay>=0){if(oathDelay>0)oathDelay--;else{strike(l,oathPath(),.48f);oathDelay=-1;}}
        if(id.isEmpty()){clock.tick();return;}String impact=clock.tick();if(impact.isEmpty())return;switch(impact){case OATH->{oathDelay=12;boss.playSound(SoundEvents.TRIDENT_RETURN,1.2f,.7f);}case CHAINS->{for(int i=0;i<4;i++)if(!broken.get(i))strike(l,chain(i),.27f);boss.playSound(SoundEvents.CHAIN_PLACE,1.1f,.65f);}case ROWERS->{rowIndex=0;sequence=1;boss.playSound(SoundEvents.PLAYER_SPLASH,1.25f,.6f);}case "basic"->strike(l,List.of(mark),.7f);default->{}}}
    private void checkLinks(ServerLevel l){var next=new ArrayList<>(broken);for(int i=0;i<4;i++)if(!next.get(i)){Vec3 p=anchor(i);var shots=l.getEntitiesOfClass(Projectile.class,new net.minecraft.world.phys.AABB(p.add(-1,-1,-1),p.add(1,1.5,1)),Projectile::isAlive);if(!shots.isEmpty()){next.set(i,true);shots.forEach(Projectile::discard);l.sendParticles(ParticleTypes.POOF,p.x,p.y,p.z,13,.25,.2,.25,.02);}}broken=List.copyOf(next);}
    private void checkRowerHits(ServerLevel l){var next=new ArrayList<>(rowerBroken);for(int i=0;i<4;i++)if(!next.get(i)){Vec3 p=rowerPosition(i);var shots=l.getEntitiesOfClass(Projectile.class,new net.minecraft.world.phys.AABB(p.add(-1,-1,-1),p.add(1,1.5,1)),Projectile::isAlive);if(!shots.isEmpty()){next.set(i,true);shots.forEach(Projectile::discard);l.sendParticles(ParticleTypes.POOF,p.x,p.y,p.z,12,.3,.2,.3,.02);}}rowerBroken=List.copyOf(next);}
    private void telegraph(ServerLevel l,String id){if(id.equals(OATH)){for(Vec3 p:oathPath())if((int)(p.x+p.z)%2==0)l.sendParticles(ParticleTypes.CRIT,p.x,p.y+.08,p.z,1,.04,.03,.04,0);}else if(id.equals(CHAINS)){for(int i=0;i<4;i++){Vec3 p=anchor(i);l.sendParticles(broken.get(i)?ParticleTypes.POOF:ParticleTypes.SOUL_FIRE_FLAME,p.x,p.y+.1,p.z,8,.2,.1,.2,0);if(!broken.get(i))for(Vec3 q:chain(i))if((int)(q.x+q.z)%3==0)l.sendParticles(ParticleTypes.SOUL,q.x,q.y+.05,q.z,1,0,0,0,0);}}else{for(int i=0;i<4;i++){Vec3 p=rowerPosition(i);l.sendParticles(rowerBroken.get(i)?ParticleTypes.POOF:ParticleTypes.SOUL,p.x,p.y+.15,p.z,7,.18,.2,.18,0);if(i!=safeGap&&!rowerBroken.get(i))for(Vec3 q:row(i))if((int)(q.x+q.z)%3==0)l.sendParticles(ParticleTypes.CLOUD,q.x,q.y+.05,q.z,1,.05,.02,.05,0);}}}
    private void strike(ServerLevel l,List<Vec3> points,float scale){for(Player p:players(l))if(points.stream().anyMatch(q->Math.abs(p.getY()-q.y)<2.7&&p.position().distanceToSqr(q)<1.55*1.55))p.hurtServer(l,boss.damageSources().mobAttack(boss),(float)(boss.getAttributeValue(Attributes.ATTACK_DAMAGE)*scale));}
    private List<Player> players(ServerLevel l){return l.getEntitiesOfClass(Player.class,boss.getBoundingBox().inflate(28),p->p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&boss.insideArena(p.position()));}
    public boolean updatePhase(float hp,float max){boolean changed=clock.updatePhase(hp,max);if(changed)phase=2;return changed;}
    public void save(ValueOutput o){clock.save(o);o.store("HrothgarOrigin",Vec3.CODEC,origin);o.store("HrothgarMark",Vec3.CODEC,mark);o.store("HrothgarBroken",com.mojang.serialization.Codec.BOOL.listOf(),broken);o.store("HrothgarRowerBroken",com.mojang.serialization.Codec.BOOL.listOf(),rowerBroken);o.putDouble("HrothgarHeading",heading);o.putInt("HrothgarPhase",phase);o.putInt("HrothgarSafeGap",safeGap);o.putInt("HrothgarOathDelay",oathDelay);o.putInt("HrothgarRowIndex",rowIndex);o.putInt("HrothgarSequence",sequence);}
    public void load(ValueInput i){clock.load(i);origin=i.read("HrothgarOrigin",Vec3.CODEC).orElse(Vec3.ZERO);mark=i.read("HrothgarMark",Vec3.CODEC).orElse(Vec3.ZERO);broken=normalize(i.read("HrothgarBroken",com.mojang.serialization.Codec.BOOL.listOf()).orElse(List.of()));rowerBroken=normalize(i.read("HrothgarRowerBroken",com.mojang.serialization.Codec.BOOL.listOf()).orElse(List.of()));heading=i.getDoubleOr("HrothgarHeading",0);phase=clock.phase();safeGap=Math.floorMod(i.getIntOr("HrothgarSafeGap",1),4);oathDelay=Math.clamp(i.getIntOr("HrothgarOathDelay",-1),-1,12);rowIndex=Math.clamp(i.getIntOr("HrothgarRowIndex",0),0,4);sequence=Math.clamp(i.getIntOr("HrothgarSequence",0),-1,8);}
    private static List<Boolean> normalize(List<Boolean> v){var r=new ArrayList<Boolean>(4);for(int n=0;n<4;n++)r.add(n<v.size()?v.get(n):false);return List.copyOf(r);}
}
